import re
from datetime import datetime

# 1. Email validator
def validate_email(email: str) -> tuple[bool, str]:
    if email.count('@') != 1:
        return False, "Email must contain exactly one '@'"
    local, domain = email.split('@')
    if not local:
        return False, "Email local part cannot be empty"
    if not domain:
        return False, "Email domain part cannot be empty"
    if '.' not in domain:
        return False, "Email domain must contain at least one dot"
    return True, ""

# 2. Phone validator
def validate_phone(phone: str) -> tuple[bool, str]:
    # Remove common symbols and spaces
    digits = re.sub(r'\D', '', phone)
    # Remove leading country code if present
    if digits.startswith('1') and len(digits) == 11:
        digits = digits[1:]
    if len(digits) != 10:
        return False, "Phone must have exactly 10 digits"
    if not digits.isdigit():
        return False, "Phone must contain only digits"
    return True, ""

# 3. URL validator
def validate_url(url: str) -> tuple[bool, str]:
    if not (url.startswith('http://') or url.startswith('https://')):
        return False, "URL must start with http:// or https://"
    try:
        scheme, rest = url.split('://', 1)
        domain = rest.split('/', 1)[0]
    except Exception:
        return False, "URL must have a valid scheme and domain"
    # Very basic domain check
    if not domain or '.' not in domain:
        return False, "URL must have a valid domain after the scheme"
    return True, ""

# 4. Date validator
def validate_date(date_str: str) -> tuple[bool, str]:
    try:
        dt = datetime.strptime(date_str, "%Y-%m-%d")
    except ValueError as e:
        return False, f"Date must be in YYYY-MM-DD and be a valid calendar date: {str(e)}"
    return True, ""

# 5. IPv4 validator
def validate_ip(ip: str) -> tuple[bool, str]:
    parts = ip.split('.')
    if len(parts) != 4:
        return False, "IPv4 address must have four octets"
    for part in parts:
        if not part.isdigit():
            return False, f"Octet '{part}' is not numeric"
        val = int(part)
        if not (0 <= val <= 255):
            return False, f"Octet '{part}' is out of range 0-255"
    return True, ""
